local a=require("tools.simrig")local function b(c)return string.format("%5.1f",c)end;local function d(c)return c*180/math.pi end;local function e(f,g,h,i)local j=a.buildStack(f,g)local k,l,m=j.flight,j.sim,j.pilot;k:handleCommand({k="gndSafety",on=false})k:handleCommand({k="flightMode",id="CRUISE"})k:handleCommand({k="masterMode",id="CPL"})k:handleCommand({k="engage"})local n={}for o,p in ipairs(i)do local q,r,s,t=0,0,0,0;local u,v,w=0,0,0;local x,y,z;local A=math.floor(p.secs/h)for B=1,A do k:step(h,p.held,l:sensors())if B==1 then x,y,z=d(m.sp.heading),m.sp.altitude,m.sp.swayPos end;l:step(h)local C=l:sensors()q=math.max(q,math.abs(d(C.pitch)))r=math.max(r,math.abs(d(C.roll)))s,t=d(C.pitch),d(C.roll)u=math.max(u,math.abs(d(C.heading)-x))v=math.max(v,math.abs(C.altitude-y))w=math.max(w,math.abs(C.swayPos-z))end;n[p.tag]={peakP=q,peakR=r,endP=s,endR=t,ovrH=u,ovrA=v,ovrS=w}end;return n end;local D={{secs=6,held={up=true},tag="climb"},{secs=3,held={},tag="s0"},{secs=6,held={surgeFwd=true},tag="surge"},{secs=3,held={surgeBack=true},tag="brake"},{secs=8,held={},tag="recover"}}local E={{secs=6,held={up=true},tag="climb"},{secs=3,held={},tag="s0"},{secs=5,held={swayRight=true},tag="strafe"},{secs=8,held={},tag="srecover"}}local F={{secs=6,held={up=true},tag="climb"},{secs=3,held={},tag="s0"},{secs=4,held={yawRight=true},tag="turn"},{secs=8,held={},tag="yawrec"}}local G={{secs=3,held={},tag="s0"},{secs=5,held={up=true},tag="climb"},{secs=8,held={},tag="altrec"}}local H={{secs=6,held={up=true},tag="climb"},{secs=3,held={},tag="s0"},{secs=4,held={swayRight=true},tag="strafe"},{secs=8,held={},tag="swayrec"}}local function I()local J={}local function K(L)J[#J+1]=L end;local m={spoolTime=0.5,tiltTrans=1.0,latRoll=0.6,surgePitch=0.1}K("simrig isolation: post-maneuver ring (peak |pitch| after brake, peak |roll| after strafe), deg")K("params: spoolTime=0.5 tiltTrans=1.0 latRoll=0.6 surgePitch=0.1")local M={swayRoll=0.10,surgePitch=-0.05,authority=0.3}local N={swayRoll=0,surgePitch=